// Generates the `allow-<command>` permissions from the command list, so capabilities/manager.json
// names permissions the build actually emitted rather than ones hand-written and hoped for
// (tauri-build 2.7 acl.rs: "permissions autogenerated in the format of `allow-$command`").
//
// Behind `gui` because a plain `cargo test` must not need tauri-build at all (AC-1).
fn main() {
    #[cfg(feature = "gui")]
    tauri_build::try_build(
        tauri_build::Attributes::new().app_manifest(
            tauri_build::AppManifest::new()
                .commands(&["pair", "install", "control", "status", "revoke"]),
        ),
    )
    .expect("failed to run tauri-build");

    // Without `gui` there is nothing to generate; the domain tests do not read the generated ACL.
}
